settings._cssCustom:
#brxe-759ec8 .thumb {
    position: relative;
}

#brxe-759ec8 .thumb::after,
#brxe-759ec8 .thumb::before {
    position: absolute;
    content: "";
    width: 100px;
    height: 50px;
    left: 50%;
    opacity: 0;
    transition: all 0.5s;
    z-index: 2;
}


#brxe-759ec8 .thumb::after {
    bottom: -1px;
    background: url(https://crowdytheme.com/assets/wp-content/uploads/2025/04/portfolio-bottom-icon.png);
    transform: translate(-50%, 30px);
        background-repeat: no-repeat;
}
#brxe-759ec8 .thumb::before {
    top: -1px;
    transform: translate(-50%, -30px);
    background: url(https://crowdytheme.com/assets/wp-content/uploads/2025/04/portfolio-top-icon.png);
        background-repeat: no-repeat;
}
#brxe-759ec8 .thumb:hover::after,
#brxe-759ec8 .thumb:hover::before {
    opacity: 1;
    transform: translate(-50%, 0);
}


html[data-brx-theme="dark"]    		#brxe-759ec8 .thumb::after, .thumb::before {
  filter: invert(1);
}

html[data-brx-theme="light"]    		#brxe-759ec8 .thumb::before {
  filter: invert(0);
}

